import{_ as r,o as a,c as o,a2 as e}from"./chunks/framework.wVcpyw2-.js";const p=JSON.parse('{"title":"投票与评选活动","description":"投票与评选活动：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/vote-selection.md","filePath":"features/vote-selection.md","lastUpdated":1785020677000}'),l={name:"features/vote-selection.md"};function n(i,t,s,d,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="投票与评选活动" tabindex="-1">投票与评选活动 <a class="header-anchor" href="#投票与评选活动" aria-label="Permalink to &quot;投票与评选活动&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按区域配置投票、评选活动的规则与权限，并管理前台发起的活动实例。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>目标区域已在 <strong>区域管理 → 区域列表</strong> 中创建。</li><li>笔记 / 圈子等基础社交能力已正常使用。</li><li>账号具备区域配置或活动管理相关权限。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="建议顺序" tabindex="-1">建议顺序 <a class="header-anchor" href="#建议顺序" aria-label="Permalink to &quot;建议顺序&quot;">​</a></h3><ol><li><strong>区域管理 → 话题配置 / 投票配置 / 评选活动配置</strong> — 先开区域开关</li><li><strong>社交圈子 → 话题管理 / 话题 PK / 话题活动 / 评选活动</strong> — 再建具体活动</li><li>客户端验收参与与结果展示</li></ol><h3 id="投票" tabindex="-1">投票 <a class="header-anchor" href="#投票" aria-label="Permalink to &quot;投票&quot;">​</a></h3><p><strong>区域规则</strong></p><p>路径：<strong>区域管理 → 投票配置</strong></p><p>设置该区域是否开放投票、每人可投次数、是否允许匿名、审核要求等（以页面字段为准）。保存后该区域用户才能正常参与。</p><p><strong>活动实例</strong></p><ul><li>笔记内联投票：用户发笔记时挂载（受笔记配置「启用投票」影响，见 <a href="/features/circle-note">圈子与笔记</a>）</li><li>违规内容：在 <strong>社交圈子 → 笔记管理</strong> 下架</li></ul><h3 id="话题-pk-话题活动" tabindex="-1">话题 PK / 话题活动 <a class="header-anchor" href="#话题-pk-话题活动" aria-label="Permalink to &quot;话题 PK / 话题活动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>区域管理 → 话题配置</strong></td><td>区域是否开放话题玩法</td></tr><tr><td><strong>社交圈子 → 话题管理</strong></td><td>维护话题</td></tr><tr><td><strong>社交圈子 → 话题 PK</strong></td><td>正反方投票类 PK</td></tr><tr><td><strong>社交圈子 → 话题活动</strong></td><td>打卡、挂载抽奖等运营活动</td></tr></tbody></table><p>先开区域话题配置，再在社交圈子里创建 PK/活动。</p><h3 id="评选活动" tabindex="-1">评选活动 <a class="header-anchor" href="#评选活动" aria-label="Permalink to &quot;评选活动&quot;">​</a></h3><p><strong>区域规则</strong></p><p>路径：<strong>区域管理 → 评选活动配置</strong></p><p>配置评选开关、报名资格、作品类型、投票权重、审核流程等区域级策略。</p><p><strong>活动实例</strong></p><p>路径：<strong>社交圈子 → 评选活动</strong></p><ol><li>新建活动：名称、时间、所属区域、规则</li><li>发布后用户投稿</li><li>后台审核作品</li><li>投票期结束后公布结果（以页面状态为准）</li></ol><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>两类配置均在 <strong>区域管理</strong> 分组下，且 <strong>按区域独立</strong>：</p><table tabindex="0"><thead><tr><th>菜单</th><th>说明</th></tr></thead><tbody><tr><td><strong>投票配置</strong></td><td>控制该区域用户能否发起 / 参与投票</td></tr><tr><td><strong>评选活动配置</strong></td><td>控制评选类活动的规则与门槛</td></tr></tbody></table><p>未单独配置的区域继承 <strong>平台默认</strong> 行（在页面顶部切换「平台默认」编辑）。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>在 <strong>投票配置</strong> 中开启目标区域投票功能。</li><li>客户端在该区域创建投票，其他用户可正常投票且次数受规则限制。</li><li>在 <strong>评选活动配置</strong> 开启后，<strong>社交圈子 → 评选活动</strong> 创建活动，用户可报名；后台审核通过后前台展示。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>用户找不到投票入口</strong></p><ul><li>确认 <strong>投票配置</strong> 已对该区域启用。</li><li>检查 UI <strong>页面配置</strong> 是否展示相关入口。</li></ul><p><strong>评选无法报名</strong></p><ul><li><strong>评选活动配置</strong> 中是否限制等级、实名或圈子成员资格。</li><li>活动是否已过报名时间（在活动列表中查看状态）。</li></ul><p><strong>票数异常</strong></p><ul><li>查看是否允许多次投票、是否开启防刷；必要时在 <strong>用户管理</strong> 处理异常账号。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/circle-note">圈子与笔记</a></li><li><a href="/config/region">区域管理</a></li></ul>',39)])])}const u=r(l,[["render",n]]);export{p as __pageData,u as default};
